import{_ as t,o as e,c as r,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const f=JSON.parse('{"title":"回答不准怎么办","description":"","frontmatter":{"title":"回答不准怎么办"},"headers":[],"relativePath":"faq/accuracy.md","filePath":"faq/accuracy.md","lastUpdated":1787948622000}'),d={name:"faq/accuracy.md"};function i(l,a,c,h,s,n){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="回答不准怎么办" tabindex="-1">回答不准怎么办 <a class="header-anchor" href="#回答不准怎么办" aria-label="Permalink to &quot;回答不准怎么办&quot;">​</a></h1><p>AI 答错、答偏、答得啰嗦，绝大多数能通过配置解决。按下面的顺序排查，基本都能定位到原因。</p><h2 id="第一步-看它引用了什么" tabindex="-1">第一步：看它引用了什么 <a class="header-anchor" href="#第一步-看它引用了什么" aria-label="Permalink to &quot;第一步：看它引用了什么&quot;">​</a></h2><p>打开<a href="/aicare-docs/workspace/records#会话详情">聊天记录</a>找到那条回复（或在<a href="/aicare-docs/solution/test">对话测试</a>里复现），查看回复详情里的<strong>参考资料</strong>：</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>引用了错的条目</td><td>知识库内容含糊或互相矛盾</td><td>修改或删掉冲突条目</td></tr><tr><td>什么都没引用</td><td>知识库缺这块内容</td><td>补充问答，见<a href="/aicare-docs/knowledge/qa-and-files">录入问答和文档</a></td></tr><tr><td>引用对了但答得不好</td><td>话术组织问题</td><td>调整 <a href="/aicare-docs/solution/agents">AI 设置</a>里的回复要求</td></tr><tr><td>路由到了错误的情景</td><td>触发规则重叠或写偏</td><td>调整<a href="/aicare-docs/solution/triggers">触发规则</a></td></tr></tbody></table><h2 id="常见问题对症下药" tabindex="-1">常见问题对症下药 <a class="header-anchor" href="#常见问题对症下药" aria-label="Permalink to &quot;常见问题对症下药&quot;">​</a></h2><h3 id="答案就是要一字不差" tabindex="-1">答案就是要一字不差 <a class="header-anchor" href="#答案就是要一字不差" aria-label="Permalink to &quot;答案就是要一字不差&quot;">​</a></h3><p>用<a href="/aicare-docs/solution/keywords">关键词回复</a>。命中关键词直接发你写的话术，AI 不参与、不会发挥。活动规则、价格承诺这类敏感内容建议都走关键词。</p><h3 id="复杂问题答得浅" tabindex="-1">复杂问题答得浅 <a class="header-anchor" href="#复杂问题答得浅" aria-label="Permalink to &quot;复杂问题答得浅&quot;">​</a></h3><p>调高<a href="/aicare-docs/solution/agents#智能程度">智能程度</a>。「快速」档处理规格比对、售后纠纷这类需要推敲的问题会吃力，换「高级」试试。注意高档位更费点数。</p><h3 id="回答和商品实际不符" tabindex="-1">回答和商品实际不符 <a class="header-anchor" href="#回答和商品实际不符" aria-label="Permalink to &quot;回答和商品实际不符&quot;">​</a></h3><p>商品资料过期了。重新跑一次<a href="/aicare-docs/knowledge/product-learn">商品学习</a>，或直接在知识库「商品」标签页改资料。</p><h3 id="该转人工的没转" tabindex="-1">该转人工的没转 <a class="header-anchor" href="#该转人工的没转" aria-label="Permalink to &quot;该转人工的没转&quot;">​</a></h3><p>检查 <a href="/aicare-docs/solution/agents#工具">AI 设置</a>里「转人工」工具是否开启、<a href="/aicare-docs/solution/transfer">转人工设置</a>里对应意图是否配置了可用对象。也可以在情景的回复设定里明确写「遇到 XX 问题直接转人工」。</p><h3 id="顾客说「答非所问」" tabindex="-1">顾客说「答非所问」 <a class="header-anchor" href="#顾客说「答非所问」" aria-label="Permalink to &quot;顾客说「答非所问」&quot;">​</a></h3><p>多半是知识条目一条塞了多个主题，检索命中后 AI 拿到一堆混杂信息。把大条目拆成一条一事的小条目。</p><h2 id="长期做法" tabindex="-1">长期做法 <a class="header-anchor" href="#长期做法" aria-label="Permalink to &quot;长期做法&quot;">​</a></h2><ul><li>每周处理一次 AI 报告的知识缺口（开启「AI 推送待办信息」通知）。</li><li>大促前把活动内容更新进知识库，结束后及时清理。</li><li>改完任何配置都用对话测试验证，再上线。</li></ul>',18)])])}const p=t(d,[["render",i]]);export{f as __pageData,p as default};
